package dev.lattenero.bot.daemon.spectator

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * THE parity gate for the renderer: 21 vectors generated by the real
 * Python (difflib + _tool_box, including a 200+ line case that exercises
 * the autojunk heuristic). Byte for byte, or the cutover never happens.
 */
class SpectatorGoldenTest {

    @Test
    fun toolBoxesAndDiffsMatchPythonByteForByte() {
        val raw = javaClass.getResourceAsStream("/spectator-golden.json")!!
            .readBytes().decodeToString()
        val cases = Json.parseToJsonElement(raw).jsonArray
        var boxes = 0
        var diffs = 0
        for (c in cases) {
            val o = c.jsonObject
            val name = o["name"]!!.jsonPrimitive.content
            val expected = o["expected"]!!.jsonPrimitive.content
            when (o["kind"]!!.jsonPrimitive.content) {
                "tool_box" -> {
                    boxes++
                    assertEquals(
                        expected,
                        ToolBox.box(o["tool"]!!.jsonPrimitive.content, o["input"]!!.jsonObject),
                        name,
                    )
                }

                "colored_diff" -> {
                    diffs++
                    val old = o["old"]!!.jsonArray.map { it.jsonPrimitive.content }
                    val new = o["new"]!!.jsonArray.map { it.jsonPrimitive.content }
                    assertEquals(expected, coloredDiff(old, new, ToolBox.CH_BOX), name)
                }
            }
        }
        assertTrue(boxes >= 10, "expected the box vectors, got $boxes")
        assertTrue(diffs >= 8, "expected the diff vectors, got $diffs")
    }
}
